package org.apache.kafka.clients.producer.internals;

import org.apache.kafka.clients.producer.Callback;
import org.apache.kafka.clients.producer.RecordMetadata;
import org.apache.kafka.common.Cluster;
import org.apache.kafka.common.Node;
import org.apache.kafka.common.PartitionInfo;
import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.common.compress.Compression;
import org.apache.kafka.common.header.Header;
import org.apache.kafka.common.header.internals.RecordHeader;
import org.apache.kafka.common.metrics.Metrics;
import org.apache.kafka.common.record.RecordBatch;
import org.apache.kafka.common.utils.LogContext;
import org.apache.kafka.common.utils.MockTime;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;

import static org.junit.jupiter.api.Assertions.*;

public class RecordAccumulatorOptimizationTest {

    private static final String TOPIC = "test-topic";
    private static final int PARTITION = 0;
    private static final int BATCH_SIZE = 1024;
    private static final long LINGER_MS = 10L;
    private static final long RETRY_BACKOFF_MS = 100L;
    private static final long RETRY_BACKOFF_MAX_MS = 1000L;
    private static final int DELIVERY_TIMEOUT_MS = 30000;
    private static final long BUFFER_MEMORY = 64 * 1024L;

    private MockTime time;
    private RecordAccumulator accumulator;
    private Metrics metrics;
    private Cluster cluster;

    @BeforeEach
    public void setUp() {
        time = new MockTime();
        metrics = new Metrics(time);
        
        Node node = new Node(0, "localhost", 9092);
        PartitionInfo partitionInfo = new PartitionInfo(TOPIC, PARTITION, node, new Node[]{node}, new Node[]{node});
        cluster = new Cluster("test-cluster", Collections.singletonList(node),
                Collections.singletonList(partitionInfo), Collections.emptySet(), Collections.emptySet());

        accumulator = new RecordAccumulator(
                new LogContext(),
                BATCH_SIZE,
                Compression.NONE,
                (int) LINGER_MS,
                RETRY_BACKOFF_MS,
                RETRY_BACKOFF_MAX_MS,
                DELIVERY_TIMEOUT_MS,
                metrics,
                "producer-metrics",
                time,
                null,
                new BufferPool(BUFFER_MEMORY, BATCH_SIZE, metrics, time, "producer-metrics")
        );
    }

    @AfterEach
    public void tearDown() {
        accumulator.close();
        metrics.close();
    }

    @Test
    public void testBatchSizeEstimationCaching() throws InterruptedException {
        byte[] key = "test-key".getBytes();
        byte[] value = "test-value".getBytes();
        Header[] headers = new Header[]{new RecordHeader("header-key", "header-value".getBytes())};

        // First append should calculate and cache the batch size estimation
        RecordAccumulator.RecordAppendResult result1 = accumulator.append(
                TOPIC, PARTITION, 0L, key, value, headers, null, 1000L, time.milliseconds(), cluster);
        assertNotNull(result1);
        assertTrue(result1.newBatchCreated);

        // Second append to the same topic should use cached estimation
        RecordAccumulator.RecordAppendResult result2 = accumulator.append(
                TOPIC, PARTITION, 0L, key, value, headers, null, 1000L, time.milliseconds(), cluster);
        assertNotNull(result2);
        assertFalse(result2.newBatchCreated); // Should append to existing batch
    }

    @Test
    public void testTopicPartitionObjectReuse() throws InterruptedException {
        byte[] key = "test-key".getBytes();
        byte[] value = "test-value".getBytes();

        // Multiple appends should reuse TopicPartition objects efficiently
        for (int i = 0; i < 5; i++) {
            RecordAccumulator.RecordAppendResult result = accumulator.append(
                    TOPIC, PARTITION, 0L, key, value, null, null, 1000L, time.milliseconds(), cluster);
            assertNotNull(result);
        }

        // Verify that batches were created efficiently
        assertTrue(accumulator.hasUndrained());
    }

    @Test
    public void testCacheMemoryCleanupOnClose() throws InterruptedException {
        byte[] key = "test-key".getBytes();
        byte[] value = "test-value".getBytes();

        // Create some cached entries
        accumulator.append(TOPIC, PARTITION, 0L, key, value, null, null, 1000L, time.milliseconds(), cluster);
        accumulator.append("another-topic", 0, 0L, key, value, null, null, 1000L, time.milliseconds(), cluster);

        // Close should clear all caches
        accumulator.close();
        
        // Verify accumulator is closed
        assertThrows(Exception.class, () -> {
            accumulator.append(TOPIC, PARTITION, 0L, key, value, null, null, 1000L, time.milliseconds(), cluster);
        });
    }

    @Test
    public void testConcurrentAppendPerformance() throws InterruptedException {
        byte[] key = "test-key".getBytes();
        byte[] value = "test-value".getBytes();
        
        long startTime = System.nanoTime();
        
        // Simulate concurrent appends
        for (int i = 0; i < 100; i++) {
            accumulator.append(TOPIC, i % 10, 0L, key, value, null, null, 1000L, time.milliseconds(), cluster);
        }
        
        long endTime = System.nanoTime();
        long durationMs = (endTime - startTime) / 1_000_000;
        
        // Performance should be reasonable (less than 100ms for 100 appends)
        assertTrue(durationMs < 100, "Append operations took too long: " + durationMs + "ms");
    }

    @Test
    public void testBatchSizeEstimationAccuracy() throws InterruptedException {
        byte[] smallKey = "k".getBytes();
        byte[] smallValue = "v".getBytes();
        byte[] largeKey = "very-long-key-that-should-affect-estimation".getBytes();
        byte[] largeValue = "very-long-value-that-should-definitely-affect-the-batch-size-estimation-logic".getBytes();

        // First append with small data
        RecordAccumulator.RecordAppendResult result1 = accumulator.append(
                TOPIC, PARTITION, 0L, smallKey, smallValue, null, null, 1000L, time.milliseconds(), cluster);
        assertNotNull(result1);

        // Second append with larger data should still work efficiently
        RecordAccumulator.RecordAppendResult result2 = accumulator.append(
                TOPIC, PARTITION + 1, 0L, largeKey, largeValue, null, null, 1000L, time.milliseconds(), cluster);
        assertNotNull(result2);
        
        // Both should have created new batches due to different partitions
        assertTrue(result1.newBatchCreated);
        assertTrue(result2.newBatchCreated);
    }

    @Test
    public void testMemoryEfficiencyWithMultipleTopics() throws InterruptedException {
        byte[] key = "test-key".getBytes();
        byte[] value = "test-value".getBytes();
        
        String[] topics = {"topic1", "topic2", "topic3", "topic4", "topic5"};
        
        // Append to multiple topics to test cache efficiency
        for (String topic : topics) {
            for (int i = 0; i < 3; i++) {
                RecordAccumulator.RecordAppendResult result = accumulator.append(
                        topic, 0, 0L, key, value, null, null, 1000L, time.milliseconds(), cluster);
                assertNotNull(result);
            }
        }
        
        // Verify that we have undrained batches
        assertTrue(accumulator.hasUndrained());
        
        // Memory usage should be reasonable
        assertTrue(accumulator.bufferPoolAvailableMemory() > 0);
    }
}

